package com.aaliyun.leadnews.wemedia.audit;
import com.aaliyun.leadnews.model.ai.ModerationDecision;import org.junit.jupiter.api.Test;import java.util.List;import static org.assertj.core.api.Assertions.assertThat;
class AuditThresholdCalibratorTest {@Test void computesCoverageAndErrorRates(){var rows=List.of(new AuditThresholdCalibrator.Row(ModerationDecision.PASS,.9,ModerationDecision.PASS),new AuditThresholdCalibrator.Row(ModerationDecision.PASS,.9,ModerationDecision.REJECT),new AuditThresholdCalibrator.Row(ModerationDecision.REJECT,.95,ModerationDecision.PASS),new AuditThresholdCalibrator.Row(ModerationDecision.REVIEW,.8,ModerationDecision.REJECT));var m=AuditThresholdCalibrator.evaluate(rows,.85,.9);assertThat(m.automaticCoverage()).isEqualTo(.75);assertThat(m.falsePassRate()).isEqualTo(.5);assertThat(m.falseRejectRate()).isEqualTo(1);}}
